            _ = url.deref();
            }
            _ = agent.notifyServerStarted(self.next_server_id, @intCast(instance.vm().hot_reload_counter), (&url), @floatFromInt(bun.timespec.now(.allow_mocked_time).ms()), instance.ptr.ptr());
        }
}

pub fn notifyServerStopped(self: HTTPServerAgent, server: jsc.API.AnyServer) void {
        if (self.agent) |agent| {
            _ = &agent;
            _ = agent.notifyServerStopped(server.inspectorServerID(), @floatFromInt(std.time.milliTimestamp()));
        }
}

pub fn notifyServerRoutesUpdated(self: HTTPServerAgent, server: jsc.API.AnyServer) !void {
        if (self.agent) |agent| {
            _ = &agent;
            const config = server.config();
            var routes = std.array_list.Managed(Route).init(bun.default_allocator);
            _ = &routes;
            defer {
            {
                for (routes.items) |*route| {
                    _ = &route;
                    _ = (route.*).deinit();
                }
                _ = routes.deinit();
            }
            }
            var max_id: u32 = 0;
            _ = &max_id;
            switch (server.userRoutes()) {
inline else => |user_routes| {
for (cp_mut_slice(&user_routes)) |*user_route| {
                _ = &user_route;
                const decl: *const jsc.API.ServerConfig.RouteDeclaration = (&(user_route.*).route);
                max_id = @max(max_id, (user_route.*).id);
                _ = try routes.append(.{ .route_id = @intCast((user_route.*).id), .path = bun.String.init(decl.path), .@"type" = .api, .param_names = null, .param_names_len = 0, .script_line = -1, .file_path = .empty });
            }
},
}
            for (config.static_routes.items) |*route| {
                _ = &route;
                _ = try routes.append(.{ .route_id = @intCast((max_id + 1)), .path = bun.String.init((route.*).path), .@"type" = (switch ((route.*).route) {
.html => .html,
.@"static" => .@"static",
else => .default,
}), .script_line = -1, .param_names = null, .param_names_len = 0, .file_path = (switch ((route.*).route) {
.html => |html| bun.String.init(html.data.bundle.data.path),
else => .empty,
}) });
                max_id = (max_id + 1);
            }
            _ = agent.notifyServerRoutesUpdated(server.inspectorServerID(), @intCast(jsc.VirtualMachine.get().hot_reload_counter), routes.items);
        }
}
