    default = 1,
    api = 2,
    html = 3,
    @"static" = 4,
};
var empty_strings: [0]BunString = &.{};

pub export fn Bun__HTTPServerAgent__setEnabled(agent: ?*InspectorHTTPServerAgent) void {
        if (jsc.VirtualMachine.get().debugger) |*debugger| {
            _ = &debugger;
            (debugger.*).http_server_agent.agent = agent;
        }
}
